package com.vehiclerental.mak.auth.service;
import com.vehiclerental.mak.auth.entity.*;import com.vehiclerental.mak.auth.repository.*;import com.vehiclerental.mak.auth.security.*;import com.vehiclerental.mak.common.exception.ApiException;
import java.util.*;import java.time.Instant;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import tools.jackson.databind.ObjectMapper;import tools.jackson.core.type.TypeReference;
@Service
public class RoleService {
 private final CustomRoleRepository roles;private final AccountRepository accounts;private final AuthControlRepository controls;private final AuthAuditRepository audits;private final ObjectMapper json;
 public RoleService(CustomRoleRepository roles,AccountRepository accounts,AuthControlRepository controls,AuthAuditRepository audits,ObjectMapper json){this.roles=roles;this.accounts=accounts;this.controls=controls;this.audits=audits;this.json=json;}
 public Set<String> permissions(Account account){return resolve(account.getRole(),account.getCustomRoleId());}
 public Set<String> resolve(String builtIn,Long id){return id==null?RolePolicy.expand(Permissions.forRole(builtIn)):roles.findById(id).map(this::grants).orElse(Set.of());}
 public String name(Account account){return name(account.getRole(),account.getCustomRoleId());}
 public String name(String builtin,Long id){return id==null?builtin:roles.findById(id).map(CustomRole::getName).orElse("Unavailable role");}
 public void validateAssignment(String builtin,Long id){if(id==null){if(!Permissions.ROLES.containsKey(builtin))throw bad("Choose a valid built-in role.");}else if(!roles.existsById(id))throw bad("The selected custom role is unavailable.");}
 @Transactional(readOnly=true) public List<Map<String,Object>> list(){var result=new ArrayList<Map<String,Object>>();for(String name:List.of("Admin","Manager","Operations","Finance","Viewer")){var item=new LinkedHashMap<String,Object>();item.put("key",name);item.put("name",name);item.put("description",switch(name){case "Admin"->"Full system access, including users and settings.";case "Manager"->"Operational and billing oversight with employee read access.";case "Operations"->"Fleet, bookings and day-to-day operations.";case "Finance"->"Billing and invoice management with operational references.";default->"Read-only access to operational records.";});item.put("builtIn",true);item.put("version",0);item.put("permissions",new TreeSet<>(RolePolicy.expand(Permissions.forRole(name))));item.put("memberCount",accounts.findAllByOrderByCreatedAtDesc().stream().filter(a->a.getCustomRoleId()==null&&name.equals(a.getRole())).count());result.add(item);}for(var r:roles.findAllByOrderByNameAsc())result.add(response(r));return result;}
 @Transactional public Map<String,Object> save(Long id,Map<String,Object> data,long actor){
  controls.lockControl().orElseThrow();var r=id==null?new CustomRole():roles.lockById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Role not found."));
  if(id!=null&&(!(data.get("version") instanceof Number n)||n.longValue()!=r.getVersion()))throw new ApiException(HttpStatus.CONFLICT,"This role changed. Reload it before saving.");
  String name=text(data.get("name")),description=text(data.get("description"));if(name.length()<2||name.length()>80||description.length()>300)throw bad("Use a role name of 2–80 characters and a description of at most 300 characters.");
  if(Permissions.ROLES.keySet().stream().anyMatch(n->n.equalsIgnoreCase(name))||roles.findAll().stream().anyMatch(x->!Objects.equals(x.getId(),id)&&x.getName().equalsIgnoreCase(name)))throw new ApiException(HttpStatus.CONFLICT,"A role with this name already exists.");
  if(!(data.get("permissions") instanceof List<?> requested)||requested.size()>100)throw bad("Choose permissions from the catalog.");var grants=new TreeSet<String>();for(Object value:requested){if(!(value instanceof String p)||!RolePolicy.catalog().contains(p))throw bad("Unknown permission.");grants.add(p);}grants.add("dashboard.read");
  for(String p:grants){int dot=p.lastIndexOf('.');String module=p.substring(0,dot);if(RolePolicy.ACTIONS.contains(p.substring(dot+1))&&!p.endsWith(".read")&&!grants.contains(module+".read"))throw bad("View access is required before granting another module action.");}
  if((grants.contains("invoices.issue")||grants.contains("invoices.credit")||grants.contains("billing-profile.write"))&&!grants.contains("invoices.read"))throw bad("Invoice view access is required for financial actions.");
  if(grants.contains("payments.refund")&&!grants.contains("bookings.read")&&!grants.contains("invoices.read"))throw bad("Booking or invoice view access is required for refunds.");
  String before=r.getPermissionsJson();r.setName(name);r.setDescription(description);r.setPermissionsJson(json.writeValueAsString(grants));r.setUpdatedAt(Instant.now());if(id==null)r.setCreatedAt(Instant.now());else r.setVersion(r.getVersion()+1);roles.saveAndFlush(r);
  if(id!=null)for(var a:accounts.findByCustomRoleId(id))a.setSessionVersion(a.getSessionVersion()+1);
  var audit=new AuthAudit();audit.setActorId(actor);audit.setEvent(id==null?"ROLE_CREATED":"ROLE_CHANGED");audit.setSummary(name+"; "+grants.size()+" permissions; "+(before==null?"new role":"assigned sessions revoked"));audit.setCreatedAt(Instant.now());audits.save(audit);return response(r);
 }
 private Set<String> grants(CustomRole role){return Set.copyOf(json.readValue(role.getPermissionsJson(),new TypeReference<List<String>>(){}));}
 private Map<String,Object> response(CustomRole role){var value=new LinkedHashMap<String,Object>();value.put("id",role.getId());value.put("key","custom:"+role.getId());value.put("name",role.getName());value.put("description",role.getDescription());value.put("builtIn",false);value.put("version",role.getVersion());value.put("permissions",new TreeSet<>(grants(role).stream().filter(RolePolicy.catalog()::contains).toList()));value.put("memberCount",accounts.countByCustomRoleId(role.getId()));return value;}
 private String text(Object v){return v==null?"":v.toString().trim();}private ApiException bad(String s){return new ApiException(HttpStatus.BAD_REQUEST,s);}
}
